/* ---------- state + storage ---------- */
const KEY = "chimen.sessions.v1";
const S = {
  screen: "home",
  session: null,
  sit: null,
  idx: 0,
  sel: null,
  lesson: 0,
  game: null,
  view: null,
  confirmClear: false,
  draft: "",
};
function loadAll() {
  try {
    return JSON.parse(localStorage.getItem(KEY) || "[]");
  } catch (e) {
    return [];
  }
}
function saveSession() {
  if (!S.session) return;
  try {
    const all = loadAll().filter((x) => x.id !== S.session.id);
    all.unshift(S.session);
    localStorage.setItem(KEY, JSON.stringify(all.slice(0, 300)));
  } catch (e) {}
}

/* ---------- speech ---------- */
let voices = [];
function loadVoices() {
  try {
    voices = speechSynthesis.getVoices();
  } catch (e) {}
}
if ("speechSynthesis" in window) {
  loadVoices();
  try {
    speechSynthesis.onvoiceschanged = loadVoices;
  } catch (e) {}
}
let player = null,
  sayBtn = null;
function stopAll() {
  if (sayBtn) {
    sayBtn.classList.remove("playing");
    sayBtn = null;
  }
  try {
    speechSynthesis.cancel();
  } catch (e) {}
  if (player) {
    player.pause();
    player.currentTime = 0;
  }
}
function playRec(src) {
  stopAll();
  try {
    if (!player) player = new Audio();
    player.src = src;
    const p = player.play();
    if (p && p.catch)
      p.catch(() =>
        toast("L'enregistrement ne peut pas être lu sur cet appareil."),
      );
  } catch (e) {
    toast("L'enregistrement ne peut pas être lu sur cet appareil.");
  }
}
function showTtsErr(btn) {
  if (!btn || document.querySelector(".tts-err")) return;
  const anchor = btn.closest(".row") || btn;
  const p = document.createElement("p");
  p.className = "tts-err note";
  p.style.cssText = "color:var(--low);margin:0;font-size:14px";
  p.textContent = L.noTts.fr;
  anchor.insertAdjacentElement("afterend", p);
}
function speak(text, lang, btn) {
  if (sayBtn) {
    sayBtn.classList.remove("playing");
    sayBtn = null;
  }
  if (player) {
    player.pause();
  }
  if (
    !("speechSynthesis" in window) ||
    typeof SpeechSynthesisUtterance === "undefined"
  ) {
    btn ? showTtsErr(btn) : toast(L.noTts.fr);
    return;
  }
  try {
    speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = "fr-FR";
    const v =
      voices.find((v) => /^fr[-_]FR/i.test(v.lang)) ||
      voices.find((v) => /^fr/i.test(v.lang));
    if (v) u.voice = v;
    u.rate = lang === "kr" ? 0.85 : 0.9;
    if (btn) {
      sayBtn = btn;
      btn.classList.add("playing");
    }
    u.onend = u.onerror = () => {
      if (sayBtn === btn) {
        sayBtn.classList.remove("playing");
        sayBtn = null;
      }
    };
    speechSynthesis.speak(u);
  } catch (e) {
    btn ? showTtsErr(btn) : toast(L.noTts.fr);
  }
}
let tt;
function toast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.hidden = false;
  clearTimeout(tt);
  tt = setTimeout(() => (t.hidden = true), 3200);
}

/* ---------- drawings ---------- */
function clockSVG(h, m) {
  const ha = (((h % 12) + m / 60) * 30 * Math.PI) / 180,
    ma = (m * 6 * Math.PI) / 180;
  let ticks = "";
  for (let i = 0; i < 12; i++) {
    const a = (i * 30 * Math.PI) / 180;
    const r1 = i % 3 ? 40 : 36;
    ticks += `<line x1="${50 + r1 * Math.sin(a)}" y1="${50 - r1 * Math.cos(a)}" x2="${50 + 44 * Math.sin(a)}" y2="${50 - 44 * Math.cos(a)}" style="stroke:var(--ink)" stroke-width="${i % 3 ? 2 : 3.5}" stroke-linecap="round"/>`;
  }
  return `<svg class="clock" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="47" style="fill:var(--surface);stroke:var(--ink)" stroke-width="3"/>${ticks}
 <line x1="50" y1="50" x2="${50 + 24 * Math.sin(ha)}" y2="${50 - 24 * Math.cos(ha)}" style="stroke:var(--ink)" stroke-width="6" stroke-linecap="round"/>
 <line x1="50" y1="50" x2="${50 + 38 * Math.sin(ma)}" y2="${50 - 38 * Math.cos(ma)}" style="stroke:var(--c,var(--sea))" stroke-width="3.5" stroke-linecap="round"/>
 <circle cx="50" cy="50" r="4" style="fill:var(--ink)"/></svg>`;
}
function marketSVG() {
  const stripes = Array.from(
    { length: 11 },
    (_, i) =>
      `<rect x="${20 + i * 20}" y="24" width="20" height="30" style="fill:var(${["--leaf", "--sun", "--hib"][i % 3]})"/>`,
  ).join("");
  const scallop = Array.from(
    { length: 11 },
    (_, i) =>
      `<path d="M${20 + i * 20} 54 q10 12 20 0z" style="fill:var(${["--leaf", "--sun", "--hib"][i % 3]})"/>`,
  ).join("");
  return `<svg class="scene" viewBox="0 0 360 230" role="img" aria-label="Au marché, une femme avec un panier achète des fruits à l'étal d'un marchand.">
 <rect width="360" height="230" rx="14" style="fill:var(--sky)"/>
 <rect y="192" width="360" height="38" style="fill:var(--ground)"/>
 ${stripes}${scallop}
 <rect x="24" y="54" width="6" height="138" style="fill:var(--wood)"/><rect x="230" y="54" width="6" height="138" style="fill:var(--wood)"/>
 <circle cx="120" cy="98" r="15" style="fill:var(--skin)"/>
 <path d="M96 146q0-34 24-34t24 34z" style="fill:var(--sea)"/>
 <rect x="168" y="76" width="56" height="28" rx="4" style="fill:var(--board)"/>
 <text x="196" y="95" text-anchor="middle" font-size="13" font-weight="700" style="fill:var(--board-ink)" font-family="Verdana,sans-serif">2 €/kg</text>
 <rect x="20" y="142" width="220" height="12" rx="3" style="fill:var(--wood)"/>
 <rect x="30" y="154" width="200" height="38" style="fill:var(--wood-d)"/>
 <circle cx="48" cy="134" r="8" style="fill:var(--hib)"/><circle cx="64" cy="134" r="8" style="fill:var(--hib)"/><circle cx="80" cy="134" r="8" style="fill:var(--hib)"/><circle cx="56" cy="122" r="8" style="fill:var(--hib)"/><circle cx="72" cy="122" r="8" style="fill:var(--hib)"/>
 <ellipse cx="112" cy="134" rx="9" ry="7" style="fill:var(--leaf)"/><ellipse cx="130" cy="134" rx="9" ry="7" style="fill:var(--leaf)"/><ellipse cx="121" cy="124" rx="9" ry="7" style="fill:var(--leaf)"/>
 <path d="M168 138q22 10 44-6" stroke-width="7" stroke-linecap="round" fill="none" style="stroke:var(--sun)"/><path d="M168 128q22 10 44-6" stroke-width="7" stroke-linecap="round" fill="none" style="stroke:var(--sun)"/>
 <circle cx="292" cy="94" r="15" style="fill:var(--skin)"/>
 <path d="M276 92q16-28 32 0z" style="fill:var(--sun)"/>
 <path d="M292 106l-28 86h56z" style="fill:var(--hib)"/>
 <path d="M282 124L244 138" stroke-width="6" stroke-linecap="round" style="stroke:var(--skin)"/>
 <path d="M304 124l14 20" stroke-width="6" stroke-linecap="round" style="stroke:var(--skin)"/>
 <path d="M306 146h26l-4 20h-18z" style="fill:var(--wood)"/><path d="M310 146q9-14 18 0" fill="none" stroke-width="3" style="stroke:var(--wood-d)"/>
 </svg>`;
}
function streetSVG() {
  const mk = (x, y, l) =>
    `<circle cx="${x}" cy="${y}" r="14" style="fill:var(--accent);stroke:var(--surface)" stroke-width="3"/><text x="${x}" y="${y + 6}" text-anchor="middle" font-size="17" font-weight="700" font-family="Verdana,sans-serif" style="fill:#1c2a31">${l}</text>`;
  return `<svg class="scene" viewBox="0 0 360 210" role="img" aria-label="Une rue avec une boulangerie, une pharmacie et une banque. Trois emplacements : A entre la boulangerie et la pharmacie, B à droite de la pharmacie, C de l'autre côté de la route.">
 <rect width="360" height="210" rx="14" style="fill:var(--sky)"/>
 <rect x="10" y="26" width="102" height="86" rx="4" style="fill:var(--sun-soft);stroke:var(--sun)" stroke-width="2"/>
 <text x="61" y="58" text-anchor="middle" font-size="12" font-weight="700" font-family="Verdana,sans-serif" style="fill:var(--ink)">Boulangerie</text>
 <rect x="138" y="26" width="88" height="86" rx="4" style="fill:var(--leaf-soft);stroke:var(--leaf)" stroke-width="2"/>
 <path d="M176 40h12v10h10v12h-10v10h-12v-10h-10v-12h10z" style="fill:var(--leaf)"/>
 <text x="182" y="98" text-anchor="middle" font-size="12" font-weight="700" font-family="Verdana,sans-serif" style="fill:var(--ink)">Pharmacie</text>
 <rect x="252" y="26" width="98" height="86" rx="4" style="fill:var(--sea-soft);stroke:var(--sea)" stroke-width="2"/>
 <text x="301" y="58" text-anchor="middle" font-size="12" font-weight="700" font-family="Verdana,sans-serif" style="fill:var(--ink)">Banque</text>
 <rect y="124" width="360" height="44" style="fill:var(--road)"/>
 <path d="M0 146h360" stroke-width="3" stroke-dasharray="16 12" style="stroke:var(--board-ink)"/>
 ${mk(125, 112, "A")}${mk(239, 112, "B")}${mk(61, 188, "C")}
 </svg>`;
}
function stim(it) {
  switch (it.stim) {
    case "market":
      return marketSVG();
    case "street":
      return streetSVG();
    case "prices":
      return `<div class="stim"><div class="sign">Tomates<small>3 € le kilo</small></div><div class="sign">Bananes<small>2 € le kilo</small></div><div class="sign">Ignames<small>4 € le kilo</small></div></div>`;
    case "change":
      return `<div class="stim"><div class="ticket">À payer<br><b>6,50 €</b></div><div class="bill" aria-label="Billet de 10 euros">10 €</div></div>`;
    case "ordo":
      return `<div class="paper"><div class="hd">Dr J. Bellance · Médecin généraliste<br>Ordonnance du 2 octobre 2026</div><p><b>Paracétamol 500 mg</b></p><p>1 comprimé le matin et 1 comprimé le soir, pendant 5 jours.</p></div>`;
    case "timetable":
      return `<div class="timetable"><div class="ln"><span class="badge">2</span> Centre-ville → Zone d'activités</div><div style="font-size:14px;opacity:.85;margin-top:4px">Départs du matin · Du lundi au vendredi</div><div class="times"><span>6 h 45</span><span>7 h 15</span><span>7 h 45</span><span>8 h 30</span></div></div>`;
    case "letter":
      return `<div class="paper"><div class="hd">Mairie · Service des titres d'identité<br>Le 28 septembre 2026</div><p>Madame, Monsieur,</p><p>Votre demande de carte d'identité est incomplète. Merci d'envoyer une copie d'un <b>justificatif de domicile</b> (facture d'eau ou d'électricité) avant le <b>30 octobre 2026</b>.</p><p>Sans ce document, votre demande ne pourra pas être traitée.</p></div>`;
  }
  return "";
}

/* ---------- screens ---------- */
const sitById = (id) => SITS.find((s) => s.id === id);
function sitProgress(sess, id) {
  const it = ITEMS[id];
  return { n: it.filter((x) => sess.ans[x.id]).length, t: it.length };
}

