function profile() {
  const p = S.session.profile;
  const qs = PQ.filter((q) => !q.when || q.when(p));
  const complete = qs.every((q) => p[q.k]);
  return `<section class="screen">
  ${bi(L.profTitle, "h1", "h")}
  ${bi(L.profLead, "p", "lead")}
  ${qs
    .map(
      (q) => `<div class="panel" data-col="sea">
    ${bi(q.q, "h2", "q")}
    ${sayBtns({ kr: q.q.kr + " " + q.o.map((o) => o[1].kr).join(", ") + ".", fr: q.q.fr + " " + q.o.map((o) => o[1].fr).join(", ") + "." })}
    <div class="opts">${q.o.map(([v, o]) => `<button class="opt" data-act="prof" data-k="${q.k}" data-v="${v}" aria-pressed="${p[q.k] === v}">${bi(o, "span")}</button>`).join("")}</div>
  </div>`,
    )
    .join("")}
  <div><button class="btn primary" data-act="toMenu" ${complete ? "" : "disabled"}>${bi(L.next, "span")}${ic("next")}</button></div>
 </section>`;
}
function menu() {
  const sess = S.session;
  const any = SITS.some((s) => sitProgress(sess, s.id).n > 0);
  return `<section class="screen">
  <div>${bi({ kr: "Bonjou " + esc(sess.name) + " !", fr: "Bonjour " + esc(sess.name) + " !" }, "h1", "h")}</div>
  ${bi(L.choose, "p", "lead")}
  ${sayBtns({ kr: L.choose.kr + ". " + L.chooseLead.kr, fr: L.choose.fr + ". " + L.chooseLead.fr })}
  <div class="sits">${SITS.map((s) => {
    const pr = sitProgress(sess, s.id);
    const pct = Math.round((100 * pr.n) / pr.t);
    return `<button class="sit" data-act="sit" data-id="${s.id}" data-col="${s.col}">
    <span class="ic">${ic(s.icon, 28)}</span>
    ${bi({ kr: s.kr, fr: s.fr }, "span", "nm")}
    ${bi(s.intro, "span", "note")}
    <span class="mini"><span class="bar"><i style="width:${pct}%"></i></span>${pr.n === pr.t ? ic("check", 18) + " Terminé" : pr.n + " / " + pr.t}</span>
   </button>`;
  }).join("")}</div>
  <div class="tools">
   <button class="tool" data-act="lessons">${ic("book", 28)}${bi(L.lessons, "span")}</button>
   <button class="tool" data-act="game">${ic("cards", 28)}${bi(L.game, "span")}</button>
   <button class="tool" data-act="results" ${any ? "" : "disabled"}>${ic("chart", 28)}${bi(L.bilan, "span")}</button>
  </div>
 </section>`;
}
function item() {
  const s = sitById(S.sit),
    list = ITEMS[S.sit],
    it = list[S.idx],
    sess = S.session;
  const dots = list
    .map(
      (x, i) =>
        `<span class="dot ${i === S.idx ? "cur" : sess.ans[x.id] ? "done" : ""}"></span>`,
    )
    .join("");
  let body = "";
  if (it.audio) {
    const tag =
      it.audio.lang === "kr"
        ? { kr: "Mésaj-la an kréyòl", fr: "Message en créole" }
        : { kr: "Mésaj-la an fransé", fr: "Message en français" };
    body += `<button class="audiobox" data-act="say" data-lang="${it.audio.lang}" data-text="${esc(it.audio.text)}"><span class="pl">${ic("play", 30)}</span><span>${bi(L.listenMsg, "span")}<span class="tag">${tag.fr} · ${L.again.fr}</span></span></button>`;
  }
  if (it.stim) body += stim(it);
  if (it.type === "text") {
    const prev = sess.ans[it.id]?.value || "";
    body += `<label for="txt" class="sr">Votre texte</label><textarea id="txt" placeholder="…">${esc(prev)}</textarea>`;
  } else if (it.type === "form") {
    const prev = sess.ans[it.id]?.value || {};
    body += `<div class="panel form">${FORM.map((f) => `<div><label for="${f.id}">${bi(f.l, "span")}</label><input type="text" id="${f.id}" autocomplete="off" placeholder="${f.ph || ""}" value="${esc(prev[f.id] || "")}"></div>`).join("")}</div>`;
  } else {
    const long = it.opts.some(
      (o) => typeof o[0] === "string" && o[0].length > 14,
    );
    body += `<div class="opts ${long ? "long" : ""}">${it.opts.map((o, i) => `<button class="opt" data-act="opt" data-i="${i}" aria-pressed="${S.sel === i}">${it.clock ? clockSVG(o[0][0], o[0][1]) + `<span class="sr">Horloge ${i + 1}</span>` : esc(o[0])}</button>`).join("")}</div>`;
  }
  const canGo = it.type ? true : S.sel !== null;
  return `<section class="screen" data-col="${s.col}">
  <div class="sitbar"><span class="ic">${ic(s.icon, 26)}</span>${bi({ kr: s.kr, fr: s.fr }, "span", "nm")}</div>
  <div class="panel"><div class="qcount"><span class="dots" aria-label="Question ${S.idx + 1} sur ${list.length}">${dots}</span><span class="eyebrow">Question</span>&ensp;<strong class="qnum">${S.idx + 1}&thinsp;/&thinsp;${list.length}</strong></div>${bi(it.q, "h1", "q")}${sayBtns(it.q)}</div>
  ${body}
  <div class="actions">
   <button class="btn ghost small" data-act="quit">${ic("back", 20)}${bi(L.quit, "span")}</button>
   <div class="row">
    ${it.type ? "" : `<button class="btn ghost" data-act="skip">${bi(L.dunno, "span")}</button>`}
    <button class="btn primary" data-act="validate" ${canGo ? "" : "disabled"}>${bi(L.validate, "span")}${ic("next")}</button>
   </div>
  </div>
 </section>`;
}
function sitdone() {
  const s = sitById(S.sit);
  const allDone = SITS.every(
    (x) => sitProgress(S.session, x.id).n === ITEMS[x.id].length,
  );
  return `<section class="screen" data-col="${s.col}">
  <div class="sitbar"><span class="ic">${ic(s.icon, 26)}</span>${bi({ kr: s.kr, fr: s.fr }, "span", "nm")}</div>
  ${bi(L.done, "h1", "h")}
  ${sayBtns(L.done)}
  <div class="row">
   <button class="btn ${allDone ? "ghost" : "primary"}" data-act="toMenu">${bi(L.back, "span")}</button>
   ${allDone ? `<button class="btn primary" data-act="results">${bi(L.bilan, "span")}${ic("next")}</button>` : ""}
  </div>
 </section>`;
}

/* ---------- scoring + bilan ---------- */
function agg(sess) {
  const a = {};
  for (const k in SKILLS) a[k] = { s: 0, m: 0, n: 0 };
  for (const s of SITS)
    for (const it of ITEMS[s.id]) {
      const r = sess.ans[it.id];
      if (r) {
        a[it.skill].s += r.score;
        a[it.skill].m += r.max;
        a[it.skill].n++;
      }
    }
  for (const k in a)
    a[k].pct = a[k].m ? Math.round((100 * a[k].s) / a[k].m) : null;
  return a;
}
function level(p) {
  if (p === null) return { c: "var(--muted)", kr: "Pa fèt", fr: "Non évalué" };
  if (p < 40) return { c: "var(--low)", kr: "Pou ranfòsé", fr: "À renforcer" };
  if (p < 75) return { c: "var(--warn)", kr: "Ka vini", fr: "En cours" };
  return { c: "var(--ok)", kr: "Ja la", fr: "Acquis" };
}
const PLAB = {
  home: "Langue à la maison",
  school: "Scolarité",
  schoolLang: "Langue de scolarisation",
  work: "Langue au travail",
};
function profLabel(k, v) {
  const q = PQ.find((q) => q.k === k);
  const o = q && q.o.find((o) => o[0] === v);
  return o ? o[1].fr : "—";
}
function orient(sess, a) {
  const p = sess.profile,
    P = (k) => a[k].pct,
    out = [];
  const lowLit =
    (P("lecture") !== null && P("lecture") < 60) ||
    (P("ecrit") !== null && P("ecrit") < 50);
  if (p.school === "never")
    out.push(
      "<b>Piste : alphabétisation.</b> La personne déclare ne pas avoir été scolarisée : l'entrée dans l'écrit est à construire, en s'appuyant sur ses compétences orales et ses stratégies du quotidien.",
    );
  else if (p.schoolLang === "other")
    out.push(
      "<b>Piste : français langue étrangère (FLE).</b> Scolarisation dans une autre langue : les acquis scolaires existent et peuvent être transférés" +
        (P("oralFR") !== null && P("oralFR") < 60
          ? " ; la compréhension orale du français est à travailler en priorité."
          : "."),
    );
  else if (lowLit)
    out.push(
      "<b>Piste : situation d'illettrisme possible.</b> Scolarisation en français, mais lecture et/ou écrit fragiles. Préciser le degré (référentiel national) lors d'un entretien et d'une observation en situation.",
    );
  else if (
    (P("calcul") !== null && P("calcul") < 60) ||
    (P("reperes") !== null && P("reperes") < 60)
  )
    out.push(
      "<b>Piste : remise à niveau ciblée.</b> Lecture et écrit mobilisés ; besoins repérés en " +
        [
          P("calcul") < 60 ? "calcul" : null,
          P("reperes") < 60 ? "repères temps/espace" : null,
        ]
          .filter(Boolean)
          .join(" et ") +
        ".",
    );
  else
    out.push(
      "<b>Compétences de base globalement mobilisées</b> sur les situations proposées.",
    );
  if (
    P("oralKR") !== null &&
    P("oralFR") !== null &&
    P("oralKR") - P("oralFR") >= 30
  )
    out.push(
      "<b>Appui sur le créole :</b> la compréhension orale est nettement plus solide en créole qu'en français. Utiliser le créole comme langue-ressource (consignes, explications, passerelles kréyòl → fransé).",
    );
  if (["kr", "both"].includes(p.home) || ["kr", "both"].includes(p.work))
    out.push(
      "<b>Contexte diglossique :</b> le créole est présent " +
        [
          ["kr", "both"].includes(p.home) ? "à la maison" : null,
          ["kr", "both"].includes(p.work) ? "au travail" : null,
        ]
          .filter(Boolean)
          .join(" et ") +
        ". Distinguer ce qui relève de la langue (français) de ce qui relève des savoirs de base.",
    );
  const notDone = SITS.filter(
    (s) => sitProgress(sess, s.id).n < ITEMS[s.id].length,
  ).map((s) => s.fr);
  if (notDone.length)
    out.push("Situations non terminées : " + notDone.join(", ") + ".");
  out.push(
    "<i>Repérage indicatif, à compléter par un entretien, la connaissance du parcours et une observation en situation.</i>",
  );
  return out;
}
function bilanText(sess) {
  const a = agg(sess);
  let t = `BILAN CHIMEN — ${sess.name}\n${new Date(sess.start).toLocaleString("fr-FR")}\n\nProfil langagier\n`;
  for (const k in PLAB)
    if (sess.profile[k])
      t += `- ${PLAB[k]} : ${profLabel(k, sess.profile[k])}\n`;
  t += `\nCompétences\n`;
  for (const k in SKILLS) {
    const l = level(a[k].pct);
    t += `- ${SKILLS[k].fr} : ${a[k].pct === null ? "non évalué" : a[k].pct + " % (" + l.fr + ")"}\n`;
  }
  t +=
    `\nPistes\n` +
    orient(sess, a)
      .map((x) => "- " + strip(x))
      .join("\n");
  const m6 = sess.ans.m6?.value;
  if (m6) t += `\n\nÉcrit (description de l'image) : « ${m6} »`;
  const f = sess.ans.l4?.value;
  if (f)
    t += `\nFormulaire : ${FORM.map((x) => x.l.fr.split(" (")[0] + " = " + (f[x.id] || "—")).join(" ; ")}`;
  return t;
}
