/* ---------- render + events ---------- */
const app = document.getElementById("app");
function render(focusTop = true) {
  const v = {
    home,
    profile,
    menu,
    item,
    sitdone,
    results,
    trainer,
    lessons,
    game,
    apropos,
    contact,
  }[S.screen];
  app.innerHTML = v();
  app.classList.toggle("home-wrap", S.screen === "home");
  if (focusTop) {
    window.scrollTo({ top: 0 });
  }
  requestAnimationFrame(() => {
    app.querySelectorAll("[data-w]").forEach((el) =>
      requestAnimationFrame(() => {
        el.style.width = el.dataset.w + "%";
      }),
    );
  });
  document.querySelectorAll("#sitenav .navlink").forEach((btn) => {
    btn.removeAttribute("aria-current");
    if (
      btn.dataset.act === S.screen ||
      (S.screen === "home" && btn.dataset.act === "home")
    )
      btn.setAttribute("aria-current", "page");
  });
}
function record(it, score, max, value) {
  S.session.ans[it.id] = { score, max, value, at: Date.now() };
  saveSession();
}
function nextItem() {
  S.sel = null;
  if (S.idx < ITEMS[S.sit].length - 1) {
    S.idx++;
    S.screen = "item";
  } else {
    S.screen = "sitdone";
  }
  render();
}

document.addEventListener("submit", (e) => {
  if (e.target.id !== "startForm") return;
  e.preventDefault();
  const name = document.getElementById("name").value.trim();
  if (!name) {
    document.getElementById("nameErr").hidden = false;
    document.getElementById("name").focus();
    return;
  }
  S.session = {
    id: "s" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name,
    start: Date.now(),
    profile: {},
    ans: {},
  };
  S.view = null;
  S.draft = "";
  saveSession();
  S.screen = "profile";
  render();
});
document.addEventListener("input", (e) => {
  if (e.target.id === "name") S.draft = e.target.value;
});
document.addEventListener("click", (e) => {
  const b = e.target.closest("[data-act]");
  if (!b || b.disabled) return;
  const a = b.dataset.act;
  if (a === "say") {
    speak(b.dataset.text, b.dataset.lang, b);
    return;
  }
  if (a === "play") {
    playRec(INTRO_KR);
    return;
  }
  if (a === "home") {
    try {
      speechSynthesis.cancel();
    } catch (e) {}
    S.session = null;
    S.view = null;
    S.screen = "home";
    render();
    return;
  }
  if (a === "trainer") {
    S.view = null;
    S.confirmClear = false;
    S.screen = "trainer";
    render();
    return;
  }
  if (a === "apropos") {
    S.screen = "apropos";
    render();
    return;
  }
  if (a === "contact") {
    S.screen = "contact";
    render();
    return;
  }
  if (a === "view") {
    S.view = loadAll().find((s) => s.id === b.dataset.id) || null;
    if (S.view) {
      S.screen = "results";
      render();
    }
    return;
  }
  if (a === "clear") {
    S.confirmClear = true;
    render(false);
    return;
  }
  if (a === "clearno") {
    S.confirmClear = false;
    render(false);
    return;
  }
  if (a === "clearyes") {
    try {
      localStorage.removeItem(KEY);
    } catch (e) {}
    S.confirmClear = false;
    render(false);
    toast("Passations effacées");
    return;
  }
  if (a === "copy") {
    const txt = bilanText(S.view || S.session);
    const done = () => toast("Bilan copié");
    const fail = () => {
      const ta = document.getElementById("copyArea");
      ta.hidden = false;
      ta.value = txt;
      ta.focus();
      ta.select();
      toast("Sélectionnez le texte puis copiez-le");
    };
    try {
      navigator.clipboard.writeText(txt).then(done, fail);
    } catch (err) {
      fail();
    }
    return;
  }
  if (!S.session && !["lesson", "gl", "gr", "replay"].includes(a)) return;
  switch (a) {
    case "prof":
      S.session.profile[b.dataset.k] = b.dataset.v;
      if (b.dataset.k === "school" && b.dataset.v === "never")
        delete S.session.profile.schoolLang;
      saveSession();
      render(false);
      break;
    case "toMenu":
      S.view = null;
      S.screen = S.session ? "menu" : "home";
      render();
      break;
    case "sit": {
      S.sit = b.dataset.id;
      const list = ITEMS[S.sit];
      const f = list.findIndex((x) => !S.session.ans[x.id]);
      S.idx = f < 0 ? 0 : f;
      S.sel = null;
      S.screen = "item";
      render();
      break;
    }
    case "opt":
      S.sel = +b.dataset.i;
      render(false);
      break;
    case "skip": {
      const it = ITEMS[S.sit][S.idx];
      record(it, 0, 1, null);
      nextItem();
      break;
    }
    case "validate": {
      const it = ITEMS[S.sit][S.idx];
      if (it.type === "text") {
        const v = document.getElementById("txt").value.trim();
        const w = (v.match(/[A-Za-zÀ-ÿ]{2,}/g) || []).length;
        record(it, w === 0 ? 0 : w < 3 ? 1 : 2, 2, v);
      } else if (it.type === "form") {
        const v = {};
        FORM.forEach(
          (f) => (v[f.id] = document.getElementById(f.id).value.trim()),
        );
        let sc = 0;
        if (/[A-Za-zÀ-ÿ]{2,}/.test(v.f_nom)) sc++;
        if (/[A-Za-zÀ-ÿ]{2,}/.test(v.f_prenom)) sc++;
        if (/^\d{1,2}\s*[\/.\-]\s*\d{1,2}\s*[\/.\-]\s*\d{4}$/.test(v.f_naiss))
          sc++;
        if (/[A-Za-zÀ-ÿ]{2,}/.test(v.f_commune)) sc++;
        record(it, sc, 4, v);
      } else {
        if (S.sel === null) return;
        record(it, it.opts[S.sel][1], 1, S.sel);
      }
      try {
        speechSynthesis.cancel();
      } catch (e) {}
      nextItem();
      break;
    }
    case "quit":
      try {
        speechSynthesis.cancel();
      } catch (e) {}
      S.screen = "menu";
      render();
      break;
    case "results":
      S.view = null;
      S.screen = "results";
      render();
      break;
    case "lessons":
      S.lesson = 0;
      S.screen = "lessons";
      render();
      break;
    case "lesson":
      S.lesson = Math.max(
        0,
        Math.min(LESSONS.length - 1, S.lesson + +b.dataset.d),
      );
      render();
      break;
    case "game":
    case "replay":
      newGame();
      S.screen = "game";
      render(a === "game");
      break;
    case "gl": {
      const i = +b.dataset.i;
      S.game.selL = i;
      S.game.bad = null;
      speak(S.game.pairs[i][0], "kr");
      render(false);
      break;
    }
    case "gr": {
      const g = S.game,
        i = +b.dataset.i;
      speak(g.pairs[i][1], "fr");
      if (g.selL === null) {
        toast("Écoutez d’abord un mot en créole");
        return;
      }
      g.tries++;
      if (g.selL === i) {
        g.ok.push(i);
        g.selL = null;
        g.bad = null;
        render(false);
      } else {
        g.bad = [g.selL, i];
        g.selL = null;
        render(false);
        setTimeout(() => {
          if (S.game === g) {
            g.bad = null;
            if (S.screen === "game") render(false);
          }
        }, 700);
      }
      break;
    }
  }
});
document.addEventListener("keydown", (e) => {
  if (S.screen !== "item") return;
  if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
  const n = parseInt(e.key);
  if (n >= 1 && n <= 4) {
    const opts = app.querySelectorAll('.opt[data-act="opt"]');
    if (opts[n - 1] && !opts[n - 1].disabled) opts[n - 1].click();
  }
});
render();

  // Crée une sphère dans le conteneur `box`, avec un canvas comme texture
  function makeSphere(box, canvas) {
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, box.clientWidth / box.clientHeight, 0.1, 100);
    camera.position.z = 4;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true }); // alpha = fond transparent
    renderer.setSize(box.clientWidth, box.clientHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    box.appendChild(renderer.domElement);

    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = renderer.capabilities.getMaxAnisotropy();   // bords nets

    const material = new THREE.MeshPhysicalMaterial({
      map: tex,
      roughness: 0.25,
      clearcoat: 1,              // vernis brillant
      clearcoatRoughness: 0.15
    });
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 64, 64), material);
    scene.add(sphere);

    // Lumières : reflet en haut à gauche, bord droit plus sombre
    scene.add(new THREE.AmbientLight(0xffffff, 0.85));
    const light = new THREE.DirectionalLight(0xffffff, 2.2);
    light.position.set(-3, 3, 4);
    scene.add(light);

    // Rotation à la souris ou au doigt
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.enableZoom = false;

    // Animation
    renderer.setAnimationLoop(() => {
      sphere.rotation.y += 0.005;
      controls.update();
      renderer.render(scene, camera);
    });

    // Redimensionnement responsive
    new ResizeObserver(() => {
      camera.aspect = box.clientWidth / box.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(box.clientWidth, box.clientHeight);
    }).observe(box);
  }

  // Sphère 1 : France
  makeSphere(document.getElementById('sphere3d'), drawStripes(['#1E4FB5', '#FFFFFF', '#d51010']));

  // Sphère 2 : Guadeloupe (gp.png, à placer à côté du HTML)
  const gpImg = new Image();
  gpImg.onload = () => makeSphere(document.getElementById('sphere3d-gp'), drawImageTwice(gpImg));
  gpImg.onerror = () => console.error('images/gp.png introuvable');
  gpImg.src = 'images/gp.png';
